for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">This diagram groups logical roles and alternative experiments. It does not describe every branch executing in one query.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen MCP authentication and recovery workflow steps"></div>'+walk)
reference=[('Logical UML participants', 'The diagram groups setup and alternative experiments. The local classroom OAuth provider and protected MCP service share a teaching process but represent separate logical roles. GitHub is a separate real remote service.'), ('Local OAuth scope', 'The local provider demonstrates browser consent, one-use authorization codes, state validation and S256 PKCE. It is not GitHub OAuth, a production identity provider, a dynamic-registration implementation or a third-party refresh-token flow. The access token remains on the backend.'), ('Real GitHub integration', 'The GitHub mode uses a personal access token from your local .env and the actual remote MCP endpoint. The server is restricted to read-only list_issues; the host fixes anthropics/claude-code, three issues and selected public fields. No comments, messages or writes are performed.'), ('Connection status and errors', 'MCP failure can coexist with a successful model turn and another healthy server. Initialization may show pending; inspect current status before classifying a server. Query startup, model authentication or process failure can still throw, so the host retains try/catch.'), ('Recovery demonstrated honestly', 'The recovery run fixes an intentional 503 outage and calls reconnectMcpServer on the same streaming Query. It does not claim to reproduce five automatic retries, recover an arbitrary network failure or refresh an external provider token.'), ('Credentials and recordings', 'Classroom credentials are generated per run. Actual GitHub and model tokens come from .env. The UI and recordings show redacted config, credential-channel names and boolean/status evidence. Observation downloads omit the classroom authorization URL.'), ('Token setup', 'Create a fine-grained GitHub PAT with public-repository read access and an expiration. Store it as GITHUB_MCP_TOKEN in .env and restart after saving. For this public issue-list exercise, private-repository and write permissions are unnecessary.')]

document('/walkthrough.html','How the app <em>was built.</em>','Thirteen source-linked steps explain credentials, OAuth, status and reconnection.',cards(reference)+walk)
readme='# Claude Agent SDK · Lesson 25 · MCP authentication and errors\n\nBased on Lesson25_MCP_Authentication_and_Errors.pptx. Five linked student pages with large text and coloured code in every UML step.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson25-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson25-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations use `cd .\\agent-sdk\\lesson25-mcp-auth-errors` instead of cloning. Open http://127.0.0.1:3125 and keep the terminal running. Node.js 24+, API credit, model access and internet are required. Windows may require Git Bash. No separate MCP server is needed.\n\n## Create your .env file\n\nCopy .env.example only if .env does not exist. Enter your key privately and restart after edits. The startup script loads this file; existing shell values take precedence.\n\n```dotenv\n'+env+'\n```\n\nNo Managed Agents IDs are required. Real .env, media, private workspaces and dependencies are excluded from Git.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for step in steps:readme+=f'### {step["number"]}. {step["title"]}\n\n{step["explanation"]}\n\nSource: `{step["source"]}`, lines {step["firstLine"]}–{step["lastLine"]}. Selected source; surrounding code omitted.\n\n```typescript\n{step["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## References\n\n- [Custom tools: official SDK documentation](https://code.claude.com/docs/en/agent-sdk/custom-tools)\n- [MCP authentication and errors](https://code.claude.com/docs/en/agent-sdk/mcp)\n- [GitHub MCP remote server](https://github.com/github/github-mcp-server/blob/main/docs/remote-server.md)\n- [Create a GitHub token](https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/managing-your-personal-access-tokens)\n\nRegenerate student pages with `python scripts/build-pages.py`. `npm test` checks redaction, PKCE hashing, authentication rejection, GitHub scope and startup without paid model calls.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
print('Built five Lesson 25 student pages and thirteen source-linked UML steps.')
